CREATE SCHEMA IF NOT EXISTS hn;
REVOKE ALL ON SCHEMA hn FROM PUBLIC,anon,authenticated;
GRANT USAGE ON SCHEMA hn TO service_role;
CREATE TABLE hn.users(id text PRIMARY KEY,name text NOT NULL,phone text UNIQUE,username text NOT NULL UNIQUE,code text NOT NULL UNIQUE,ref_id text REFERENCES hn.users(id) DEFERRABLE INITIALLY DEFERRED,role text NOT NULL DEFAULT 'student' CHECK(role IN ('student','staff','admin')),hn integer NOT NULL DEFAULT 0,mtd integer NOT NULL DEFAULT 0,paid integer NOT NULL DEFAULT 0,assigned text REFERENCES hn.users(id) DEFERRABLE INITIALLY DEFERRED,created text NOT NULL,mtd_at text,note text NOT NULL DEFAULT '',password_hash text NOT NULL,password_salt text NOT NULL);
CREATE INDEX users_ref_idx ON hn.users(ref_id);
CREATE INDEX users_assigned_idx ON hn.users(assigned);
CREATE TABLE hn.events(id text PRIMARY KEY,title text NOT NULL,program text NOT NULL CHECK(program IN ('one','six')),starts text NOT NULL,link text NOT NULL DEFAULT '',active integer NOT NULL DEFAULT 1,created text NOT NULL);
CREATE TABLE hn.registrations(id text PRIMARY KEY,user_id text NOT NULL REFERENCES hn.users(id),event_id text NOT NULL DEFAULT '',program text NOT NULL,status text NOT NULL DEFAULT 'pending',topic text NOT NULL DEFAULT '',need text NOT NULL DEFAULT '',created text NOT NULL,confirmed text,actor text,UNIQUE(user_id,event_id,program));
CREATE INDEX registrations_user_idx ON hn.registrations(user_id);
CREATE TABLE hn.credits(id text PRIMARY KEY,user_id text NOT NULL REFERENCES hn.users(id),source text NOT NULL UNIQUE REFERENCES hn.users(id),amount integer NOT NULL DEFAULT 200000 CHECK(amount=200000),created text NOT NULL,actor text NOT NULL);
CREATE INDEX credits_user_idx ON hn.credits(user_id);
CREATE TABLE hn.attendance(source text PRIMARY KEY REFERENCES hn.users(id),ref_id text NOT NULL REFERENCES hn.users(id),created text NOT NULL,actor text NOT NULL);
CREATE INDEX attendance_ref_idx ON hn.attendance(ref_id);
CREATE TABLE hn.lessons(id text PRIMARY KEY,position integer NOT NULL UNIQUE CHECK(position BETWEEN 1 AND 180),title text NOT NULL,kind text NOT NULL,url text NOT NULL,starts text NOT NULL DEFAULT '',created text NOT NULL);
CREATE TABLE hn.touches(id text PRIMARY KEY,user_id text NOT NULL REFERENCES hn.users(id),actor text NOT NULL,result text NOT NULL,note text NOT NULL,next text NOT NULL DEFAULT '',created text NOT NULL);
CREATE INDEX touches_user_idx ON hn.touches(user_id);
CREATE TABLE hn.reports(id text PRIMARY KEY,user_id text NOT NULL REFERENCES hn.users(id),day text NOT NULL,reached integer NOT NULL,invited integer NOT NULL,note text NOT NULL,created text NOT NULL);
CREATE INDEX reports_user_idx ON hn.reports(user_id);
CREATE TABLE hn.sessions(token text PRIMARY KEY,user_id text NOT NULL REFERENCES hn.users(id),expires text NOT NULL);
CREATE INDEX sessions_user_idx ON hn.sessions(user_id);
CREATE TABLE hn.settings(key text PRIMARY KEY,value text NOT NULL);
CREATE TABLE hn.audit(id text PRIMARY KEY,actor text NOT NULL,action text NOT NULL,target text NOT NULL,created text NOT NULL);
ALTER TABLE hn.users ENABLE ROW LEVEL SECURITY;
ALTER TABLE hn.events ENABLE ROW LEVEL SECURITY;
ALTER TABLE hn.registrations ENABLE ROW LEVEL SECURITY;
ALTER TABLE hn.credits ENABLE ROW LEVEL SECURITY;
ALTER TABLE hn.attendance ENABLE ROW LEVEL SECURITY;
ALTER TABLE hn.lessons ENABLE ROW LEVEL SECURITY;
ALTER TABLE hn.touches ENABLE ROW LEVEL SECURITY;
ALTER TABLE hn.reports ENABLE ROW LEVEL SECURITY;
ALTER TABLE hn.sessions ENABLE ROW LEVEL SECURITY;
ALTER TABLE hn.settings ENABLE ROW LEVEL SECURITY;
ALTER TABLE hn.audit ENABLE ROW LEVEL SECURITY;
GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA hn TO service_role;
